<script setup lang="ts">import type {Diagnostic} from '../types';defineProps<{diagnostics:Diagnostic[];valid?:boolean}>();</script>
<template><section class="ai-diagnostics"><h4>Validation <span :class="valid?'valid':'invalid'">{{valid===undefined?'Not run':valid?'Passed':'Failed'}}</span></h4><p v-if="valid&&!diagnostics.length" class="valid">No validation errors.</p><table v-if="diagnostics.length"><thead><tr><th>Code</th><th>Message</th><th>Location</th></tr></thead><tbody><tr v-for="(item,index) in diagnostics" :key="index"><td><code>{{item.code}}</code></td><td>{{item.message}}</td><td>{{item.line?`${item.line}:${item.column||1}`:'—'}}</td></tr></tbody></table></section></template>
